import json
import re
from typing import Any, Dict

NON_EXTRACTABLE_PATTERNS = (
    r"(effDate|expDate)$",
    r"(effRuleId|cancelRuleId)$",
    r"(prodId|pricingId|prodPrcId|inProdPrcId|outProdPrcId|billPrcId|conditionCode|groupId)$",
    r"orderNo$",
    r"groupIdMessage$",
    r"subBillPrcIds$",
    r"^optionalInfo\.prcSmsCfg\.",
    r"acctItem$",
    r"powerCode$",
    r"familyCata$",
    r"splitRate(9|6)$",
    r"(favValidityVAlue|fixValidityVAlue)$",
)
YES_HINT_WORDS = ('允许', '开通', '支持', '可以', '可办')

def _is_non_extractable(path):
    return any(re.search(p, path) for p in NON_EXTRACTABLE_PATTERNS)

def _collect_leaves(schema):
    leaves = {}
    def walk(node, prefix=''):
        props = node.get('properties') if isinstance(node, dict) else None
        if not isinstance(props, dict):
            return
        for k, v in props.items():
            p2 = (prefix + '.' + k) if prefix else k
            if isinstance(v, dict) and v.get('type') == 'object':
                walk(v, p2)
            else:
                leaves[p2] = v or {}
    walk(schema)
    return leaves

def _flatten(node, prefix='', out=None):
    if out is None:
        out = {}
    if not isinstance(node, dict):
        return out
    for k, v in node.items():
        path = (prefix + '.' + k) if prefix else k
        if isinstance(v, dict):
            _flatten(v, path, out)
        else:
            out[path] = v
    return out

def _to_number(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return v
    s = str(v).strip()
    if not s:
        return None
    try:
        return float(s) if '.' in s else int(s)
    except ValueError:
        m = re.match(r'^(\d+(?:\.\d+)?)\s*元?$', s)
        return float(m.group(1)) if m else None

async def main(args):
    p = args.params
    try:
        schema = json.loads(str(p.get('schema_json') or '{}'))
    except Exception:
        schema = {}
    try:
        elements = json.loads(str(p.get('elements_json') or '{}'))
    except Exception:
        elements = {}
    threshold = float(p.get('threshold') or 0.30)
    leaves = _collect_leaves(schema)
    flat = _flatten(elements)
    warnings, removed = [], []
    yes_norm_hints, price_cross = [], []
    valid_paths = {}
    for path, val in flat.items():
        prop = leaves.get(path)
        if prop is None:
            removed.append({'path': path, 'value': val, 'reason': 'invalid_path'})
            continue
        valid_paths[path] = (val, prop)
    for path, (val, prop) in list(valid_paths.items()):
        if prop.get('type') == 'number' and _to_number(val) is None:
            removed.append({'path': path, 'value': val, 'reason': 'invalid_number'})
            del valid_paths[path]
    for path, (val, prop) in valid_paths.items():
        label = prop.get('x-label') or ''
        enum = prop.get('enum') or []
        is_yes_no = ('是否' in label) or any(e in ('是、否', '是、否、默认') or str(e) in ('是', '否') for e in enum)
        if is_yes_no and isinstance(val, str) and any(w in val for w in YES_HINT_WORDS):
            yes_norm_hints.append({'path': path, 'value': val, 'suggest': '是'})
    extractable_required = [p for p, prop in leaves.items()
                            if prop.get('x-required') and not _is_non_extractable(p)]
    hit = [p for p in extractable_required if p in valid_paths]
    rate = (len(hit) / len(extractable_required)) if extractable_required else 1.0
    gate = 'PASS' if rate >= threshold else 'FAIL'
    pmf = _to_number(valid_paths.get('optionalInfo.printContent.prcMonthFee', (None,))[0]) \
        if 'optionalInfo.printContent.prcMonthFee' in valid_paths else None
    ff = _to_number(valid_paths.get('optionalInfo.acctMonth.fixFee', (None,))[0]) \
        if 'optionalInfo.acctMonth.fixFee' in valid_paths else None
    if pmf is not None and ff is not None and pmf != ff:
        price_cross.append({'paths': ['optionalInfo.printContent.prcMonthFee',
                                      'optionalInfo.acctMonth.fixFee'],
                            'values': [pmf, ff],
                            'note': '套餐月费与固定费不一致，请人工确认（不阻断）'})
    result = 'FAIL' if gate == 'FAIL' else ('PASS_WITH_WARNINGS' if removed else 'PASS')
    missing_required = []
    if gate == 'FAIL':
        missing_required = [
            {'path': p, 'label': (leaves[p].get('x-label') or p),
             'type': (leaves[p].get('type') or ''),
             'enum': (leaves[p].get('enum') or [])[:6],
             'hint': '原文是否提到该字段（可同义改写）；类型=%s' % (leaves[p].get('type') or '')}
            for p in extractable_required if p not in valid_paths
        ]
    ret: Output = {
        'result': result,
        'quality_gate': gate,
        'stats': json.dumps({
            'extracted_total': len(flat),
            'valid_total': len(valid_paths),
            'removed_total': len(removed),
            'required_total': sum(1 for p in leaves.values() if p.get('x-required')),
            'extractable_required_total': len(extractable_required),
            'extractable_required_hit': len(hit),
            'extractable_hit_rate': round(rate, 4),
            'threshold': threshold,
        }, ensure_ascii=False),
        'missing_required': json.dumps(missing_required, ensure_ascii=False),
        'removed': json.dumps(removed, ensure_ascii=False),
        'yes_norm_hints': json.dumps(yes_norm_hints, ensure_ascii=False),
        'price_cross_check': json.dumps(price_cross, ensure_ascii=False),
    }
    return ret

import json
from typing import Any, Dict

PRICE_KEYWORDS = ('档位', '月功能费', '月租', '月费', '固定费', '费用')
PRICE_EXCLUDE_MARKS = ('有效期', '周期', '时长', '间隔')
EMPTY_MARKS = ('', '待补充', '系统待生成')
SKIP_KEYS = ('templateId', 'prodId', 'prodPrcId', 'pricingId', 'opType')
SYSTEM_GEN_KEYS = ('orderNo',)
SAME_PARAMETER_PAIRS = (
    ('optionalInfo.printContent.prcMonthFee', 'optionalInfo.acctMonth.fixFee', '套餐月费', '套餐固定费'),
)

def is_price(label, key):
    for text in (label, key):
        t = text or ''
        if any(m in t for m in PRICE_EXCLUDE_MARKS):
            continue
        if any(kw in t for kw in PRICE_KEYWORDS):
            return True
    return False

def strip(v):
    if v is None:
        return ''
    if isinstance(v, bool):
        return '是' if v else '否'
    if isinstance(v, (int, float)):
        return v
    s = str(v).strip()
    return '' if s in EMPTY_MARKS else s

def flatten_elements(node, prefix='', out=None):
    if out is None:
        out = {}
    if not isinstance(node, dict):
        return out
    for k, v in node.items():
        path = (prefix + '.' + k) if prefix else k
        if isinstance(v, dict):
            flatten_elements(v, path, out)
        else:
            val = strip(v)
            if val != '':
                out[path] = val
    return out

def flatten_offer(node, prefix='', out=None):
    if out is None:
        out = {}
    if isinstance(node, dict):
        for k, v in node.items():
            path = (prefix + '.' + k) if prefix else k
            flatten_offer(v, path, out)
    elif isinstance(node, list):
        for i, v in enumerate(node):
            flatten_offer(v, '%s[%d]' % (prefix, i), out)
    else:
        val = strip(node)
        if val != '':
            out[prefix] = val
    return out

def merge_body(schema, elements_map, offer_map, meta, path='', pending=None):
    if pending is None:
        pending = []
    out = {}
    props = schema.get('properties') or {}
    for key, sub in props.items():
        cur = (path + '.' + key) if path else key
        label = sub.get('x-label', key)
        if sub.get('type') == 'object':
            out[key] = merge_body(sub, elements_map, offer_map, meta, cur, pending)
            continue
        val = elements_map.get(cur)
        source = '原始需求' if val is not None else ''
        if val is None and not is_price(label, key):
            oval = offer_map.get(cur)
            if oval is not None:
                val, source = oval, 'AI补全'
        if val is None and sub.get('default') is not None:
            val, source = sub['default'], '默认值'
        if val is None:
            val, source = '', ''
            if sub.get('x-required') and key not in SKIP_KEYS and key not in SYSTEM_GEN_KEYS:
                pending.append(cur)
        out[key] = val
        if source:
            meta[cur] = {'label': label, 'value': val, 'source': source}
    return out

def _num(v):
    if isinstance(v, bool) or v is None:
        return None
    try:
        return float(str(v).strip())
    except (TypeError, ValueError):
        return None

def _path_get(node, path):
    for part in path.split('.'):
        if not isinstance(node, dict) or part not in node:
            return None
        node = node[part]
    return node

def _path_set(node, path, value):
    parts = path.split('.')
    cur = node
    for part in parts[:-1]:
        if not isinstance(cur, dict):
            return
        cur = cur.setdefault(part, {})
    if isinstance(cur, dict):
        cur[parts[-1]] = value

def reconcile_same_parameter(merged, meta, pending):
    for path_a, path_b, label_a, label_b in SAME_PARAMETER_PAIRS:
        na, nb = _num(_path_get(merged, path_a)), _num(_path_get(merged, path_b))
        src_a = (meta.get(path_a) or {}).get('source', '')
        src_b = (meta.get(path_b) or {}).get('source', '')
        def _authority():
            if na is None and nb is None:
                return None
            pri = {'原始需求': 0, '存量提取': 0, 'AI补全': 1, '同源派生': 2, '默认值': 2}
            rank_a, rank_b = pri.get(str(src_a), 2), pri.get(str(src_b), 2)
            if na is not None and nb is not None:
                if na == nb:
                    return None
                return (na, path_a, label_a) if (rank_a, path_a) <= (rank_b, path_b) else (nb, path_b, label_b)
            return (na, path_a, label_a) if na is not None else (nb, path_b, label_b)
        auth = _authority()
        if auth is None:
            continue
        value, apath, alabel = auth
        for path, label in ((path_a, label_a), (path_b, label_b)):
            if _num(_path_get(merged, path)) != value:
                _path_set(merged, path, value)
                meta[path] = {'label': label, 'value': value, 'source': '同源派生(%s)' % alabel}
                if path in pending:
                    pending.remove(path)

async def main(args):
    p = args.params
    def load(text):
        if not isinstance(text, str) or not text.strip():
            return {}
        try:
            return json.loads(text)
        except Exception:
            try:
                t = text.strip()
                if ':' in t and not t.startswith('{') and not t.startswith('['):
                    t = t.split(':', 1)[1].strip()
                return json.loads(t)
            except Exception:
                return {}
    schema = load(p.get('schema_json') or '')
    elements = load(p.get('elements_json') or '')
    offer = load(p.get('offer_json') or '')
    template_id = schema.get('x-template', '')
    if isinstance(offer, dict) and template_id in offer:
        offer = offer[template_id]
    elements_map = flatten_elements(elements)
    offer_map = flatten_offer(offer)
    meta, pending = {}, []
    merged = merge_body(schema, elements_map, offer_map, meta, pending=pending)
    reconcile_same_parameter(merged, meta, pending)
    ret: Output = {
        "payload": json.dumps(merged, ensure_ascii=False),
        "meta": json.dumps(meta, ensure_ascii=False),
        "pending_required": ','.join(pending),
        "template": template_id,
    }
    return ret

import json, urllib.request
from typing import Any, Dict

VALIDATE_URL = 'http://10.86.13.201:31281/api/v1/appstore/validate-nested'

def _fetch(payload, template_id):
    body = json.dumps({'payload': payload, 'template_id': template_id}).encode('utf-8')
    req = urllib.request.Request(VALIDATE_URL, data=body, method='POST',
                                 headers={'Content-Type': 'application/json'})
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.loads(resp.read().decode('utf-8'))

async def main(args):
    p = args.params
    payload = str(p.get('payload') or '')
    template_id = str(p.get('template_id') or '')
    try:
        info = _fetch(payload, template_id)
    except Exception:
        info = None
    if not info:
        ret: Output = {
            'backend_pending': '1',
            'valid': '',
            'error_list': '[]',
            'explain': '',
            'note': '本体校验闸(validate_nested)端点暂不可达，未执行本体校验；方案仍按原链路给出（单产品闭合）',
        }
    else:
        def _arr(v):
            return json.dumps(v, ensure_ascii=False) if isinstance(v, (list, dict)) else str(v or '')
        ret: Output = {
            'backend_pending': '0',
            'valid': str(info.get('valid') or ''),
            'error_list': _arr(info.get('error_list')),
            'explain': _arr(info.get('explain')),
            'note': str(info.get('message') or ''),
        }
    return ret

import json
from typing import Any, Dict

SKIP_KEYS = ('templateId', 'prodId', 'prodPrcId', 'pricingId', 'opType')
SYSTEM_GEN_KEYS = ('orderNo',)
SOURCE_MAP = {
    '原始需求': '原始需求提取', 'AI补全': '复用相似产品',
    '本体推理': '本体推理', '默认值': '默认值', '同源派生': '同源派生',
}
SIMILAR_REF_PREFIX = '参考相似产品: '
INDENT_UNIT = '　'
OVERVIEW_PATHS = (
    ('baseInfo.prodPrcName', '资费名称'),
    ('optionalInfo.printContent.prcMonthFee', '套餐月费'),
    ('optionalInfo.printContent.containResource', '包含资源'),
)

def has_business_value(sub_schema, sub_data):
    if isinstance(sub_data, dict):
        for v in sub_data.values():
            if v not in ('', None, [], {}):
                return True
        return False
    return False

def fmt_value(v):
    if isinstance(v, bool):
        return '是' if v else '否'
    if isinstance(v, list):
        return '、'.join(str(x) for x in v)
    return str(v)

def similar_ref(similar_offer):
    if not isinstance(similar_offer, dict):
        return ''
    oid = similar_offer.get('similarOfferId', '')
    oname = similar_offer.get('similarOfferName', '')
    if isinstance(oid, (int, float)):
        oid = str(oid)
    if not oid or not oname:
        return ''
    return '%s%s %s' % (SIMILAR_REF_PREFIX, str(oid), str(oname))

def collect(schema, data, pending, meta=None, sim_ref=''):
    sections = []
    meta = meta or {}
    def walk(obj_schema, obj_data, depth, path, sec):
        for key, sub in obj_schema.get('properties', {}).items():
            label = sub.get('x-label', key)
            cur = (path + '.' + key) if path else key
            if sub.get('type') == 'object':
                sub_data = obj_data.get(key, {}) if isinstance(obj_data, dict) else {}
                if not has_business_value(sub, sub_data):
                    continue
                if depth <= 1:
                    sec2 = {'title': label, 'rows': []}
                    sections.append(sec2)
                    walk(sub, sub_data, depth + 1, cur, sec2)
                else:
                    sec['rows'].append(('s', depth, label, '', '', ''))
                    walk(sub, sub_data, depth + 1, cur, sec)
            else:
                if key in SKIP_KEYS or not isinstance(obj_data, dict):
                    continue
                if key not in obj_data or obj_data[key] in ('', None):
                    if sub.get('x-required') and key not in SYSTEM_GEN_KEYS:
                        pending.append((INDENT_UNIT * depth) + label)
                    continue
                val = fmt_value(obj_data[key])
                note_parts = []
                cond = sub.get('x-show-when')
                if cond:
                    note_parts.append('满足条件时展示：' + str(cond).rstrip('才展示展示'))
                entry = meta.get(cur) or {}
                source_raw = entry.get('source', '') if isinstance(entry, dict) else ''
                source = SOURCE_MAP.get(source_raw, source_raw)
                if source_raw == 'AI补全' and sim_ref:
                    source = sim_ref
                sec['rows'].append(('|', depth, label, val, source, '；'.join(note_parts)))
    top = {'title': '', 'rows': []}
    sections.append(top)
    walk(schema, data, 0, '', top)
    return [s for s in sections if s['rows']]

async def main(args):
    p = args.params
    def load(text):
        if not isinstance(text, str) or not text.strip():
            return {}
        try:
            return json.loads(text)
        except Exception:
            try:
                t = text.strip()
                if ':' in t and not t.startswith('{') and not t.startswith('['):
                    t = t.split(':', 1)[1].strip()
                return json.loads(t)
            except Exception:
                return {}
    schema = load(p.get('schema_json') or '')
    data = load(p.get('payload') or '')
    meta = load(p.get('meta') or '')
    similar_offer = load(p.get('similar_offer') or '')
    title = str(p.get('title') or '')
    if schema.get('x-template') in data:
        data = data[schema['x-template']]
    pending = []
    sim_ref = similar_ref(similar_offer)
    sections = collect(schema, data, pending, meta, sim_ref)
    lines = []
    if title:
        lines.append('## ' + title)
        lines.append('')
    overview = []
    for dotted, cn in OVERVIEW_PATHS:
        node = data
        for k in dotted.split('.'):
            node = node.get(k) if isinstance(node, dict) else None
        if node not in ('', None):
            overview.append('**%s**：%s' % (cn, fmt_value(node)))
    if overview:
        lines.append('> **套餐概览**　|　' + '　|　'.join(overview))
        lines.append('')
    n = 0
    for sec in sections:
        if not sec['rows']:
            continue
        n += 1
        title_txt = '%d. %s' % (n, sec['title']) if sec['title'] else '%d. 配置明细' % n
        lines.append('**%s**' % title_txt)
        lines.append('')
        lines.append('| 字段名称 | 字段值 | 取值来源 | 备注 |')
        lines.append('| :--- | :--- | :--- | :--- |')
        for kind, depth, label, val, source, note in sec['rows']:
            if kind == 's':
                lines.append('| **%s%s** |  |  |  |' % (INDENT_UNIT * (depth - 1), label))
            else:
                pad = INDENT_UNIT * (depth - 1) if depth > 0 else ''
                lines.append('| %s%s | %s | %s | %s |' % (pad, label, val, source, note))
        lines.append('')
    if pending:
        lines.append('**【待补充字段】**（%d 项，补充后可进入配置）：' % len(pending))
        lines.append('、'.join(pending))
        lines.append('')
    ret: Output = {
        "table_text": '\n'.join(lines),
        "pending_count": str(len(pending)),
    }
    return ret

